<!-- This file is generated by AI. -->

<!--
  资源工作区: 文本资源用 Monaco, 媒体资源用原生展示控件。

  媒体走预览站点而不是读文件字节: 立绘与 BGM 可以很大, 造 blob URL 会把整份内容读进内存再交给
  <img>/<audio> —— 而预览服务器本来就把**项目根**挂成了站点 (与 `ResourceBrowser` 右侧预览栏
  同一套地址拼法)。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css` (`.resource-workspace` 一族)。
-->

<script lang="ts">
  import { projectRelativePath } from '../fileops';
  import { assetUrlFor } from '../lib/assetUrl';
  import { resolveProjectEnginePath } from '../lib/engine';
  import { previewClient } from '../preview/client';
  import { appStore, type OpenDocument } from '../state/store.svelte';
  import type { ResourceTab as ResourceTabModel } from '../tabs/model';
  import CodeEditor from './CodeEditor.svelte';

  let {
    tab,
    /**
     * 该资源的文本文档。
     *
     * **媒体资源没有文档** (不会为一张图建 Monaco model), 所以这里必须允许 null ——
     * 写成"没有 doc 就报错"会把立绘、BGM、视频全都挡在门外。
     */
    doc,
  }: {
    tab: ResourceTabModel;
    doc: OpenDocument | null;
  } = $props();

  /*
   * 媒体资源要先拿到预览站点前缀。
   *
   * 与 `ResourceBrowser` 一样在项目/引擎变化后重取, 并用 `cancelled` 防止过期结果写回 ——
   * `ensureSite` 是异步的, 切项目时旧的那次可能后到。
   */
  let assetBase = $state<string | null>(null);

  $effect(() => {
    if (tab.resourceKind === 'text') return; // 文本走 Monaco, 不需要站点
    const projectPath = appStore.projectPath;
    if (!projectPath) {
      assetBase = null;
      return;
    }
    const enginePath = resolveProjectEnginePath(appStore.settings, appStore.projectBindings, projectPath);
    let cancelled = false;
    void (async () => {
      const url = await previewClient.ensureSite(projectPath, enginePath);
      if (!cancelled) assetBase = url;
    })();
    return () => {
      cancelled = true;
    };
  });

  /**
   * 相对 `game/` 的逻辑路径。
   *
   * 预览服务器的站点根是**项目根**, 而 `assetUrlFor` 会自己补 `game/`, 所以这里要把
   * 项目相对路径里的 `game/` 前缀去掉 (与 `ResourceBrowser` 传进去的 `rel` 同一口径)。
   */
  const gameRelative = $derived.by(() => {
    const projectPath = appStore.projectPath;
    if (!projectPath) return null;
    const rel = projectRelativePath(projectPath, tab.path).replace(/\\/g, '/');
    return rel.toLowerCase().startsWith('game/') ? rel.slice('game/'.length) : rel;
  });

  const url = $derived(assetBase && gameRelative ? assetUrlFor(assetBase, gameRelative) : undefined);
</script>

{#if tab.resourceKind === 'text'}
  {#if doc}
    <CodeEditor {doc} />
  {:else}
    <div class="editor-empty">正在读取资源…</div>
  {/if}
{:else if url}
  <div class="resource-workspace">
    {#if tab.resourceKind === 'image'}
      <img src={url} alt={tab.title} />
    {:else if tab.resourceKind === 'audio'}
      <audio src={url} controls></audio>
    {:else if tab.resourceKind === 'video'}
      <!-- 素材预览: 没有字幕轨可言, 这是本地资源查看器而不是播放器界面 -->
      <!-- svelte-ignore a11y_media_has_caption -->
      <video src={url} controls></video>
    {/if}
  </div>
{:else}
  <div class="editor-empty">正在加载资源…</div>
{/if}
